contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes all parameters forwarded to setL1BlockValues plus a flag indicating whether
    // to call from the depositor (true) or from a non-depositor (false).
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar,
        bool callAsDepositor
    ) public payable {
        // Read all public getters before the attempt
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequenceNumber = c.sequenceNumber();
        bytes32 before_batcherHash = c.batcherHash();
        uint256 before_l1FeeOverhead = c.l1FeeOverhead();
        uint256 before_l1FeeScalar = c.l1FeeScalar();

        bool reverted;

        if (callAsDepositor) {
            // We must simulate calling as the depositor account. The test contract itself
            // is the msg.sender when calling c; the depositor in contract C is a fixed
            // constant address. To achieve the intended behavior, we rely on the fact
            // that the checker will deploy C beforehand and will allow the test contract
            // to be the depositor only when appropriate. Here we attempt the call and
            // record if it reverted.
            try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Call as non-depositor (the test contract). This should revert due to onlyDepositor.
            try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read all public getters after the attempt
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequenceNumber = c.sequenceNumber();
        bytes32 after_batcherHash = c.batcherHash();
        uint256 after_l1FeeOverhead = c.l1FeeOverhead();
        uint256 after_l1FeeScalar = c.l1FeeScalar();

        // General rule:
        // - If the call did NOT revert then the stored values must equal the provided inputs.
        // - If the call DID revert then none of the stored values change (they remain equal to before-values).
        assert(
            ( !reverted
                && after_number == _number
                && after_timestamp == _timestamp
                && after_basefee == _basefee
                && after_hash == _hash
                && after_sequenceNumber == _sequenceNumber
                && after_batcherHash == _batcherHash
                && after_l1FeeOverhead == _l1FeeOverhead
                && after_l1FeeScalar == _l1FeeScalar
            )
            ||
            ( reverted
                && after_number == before_number
                && after_timestamp == before_timestamp
                && after_basefee == before_basefee
                && after_hash == before_hash
                && after_sequenceNumber == before_sequenceNumber
                && after_batcherHash == before_batcherHash
                && after_l1FeeOverhead == before_l1FeeOverhead
                && after_l1FeeScalar == before_l1FeeScalar
            )
        );
    }

    receive() external payable {}
}

